def apply_visual_design():
    """Apply the requested decorative theme while keeping native accessible UI controls."""
    # The user explicitly requested textures and shadows; static CSS contains no app data.
    st.html(config.THEME_CSS_FILE)
    # Numeric geometry shares one source of truth with the time-axis calculations.
    st.html('<style>:root{'
            f'--ww-hour-height:{config.CALENDAR_HOUR_HEIGHT}px;'
            f'--ww-track-height:{config.CALENDAR_TRACK_HEIGHT}px;'
            '}</style>')
    st.logo(str(config.APP_WORDMARK_FILE), size='large', icon_image=str(config.APP_ICON_FILE))


def render_chart(figure, alt):
    """Match a detached chart to Navy & Oak without changing data or global plot settings."""
    palette = config.CHART_THEME
    figure.set_facecolor(palette['background'])
    for axis in figure.axes:
        axis.set_facecolor(palette['background'])
        axis.tick_params(colors=palette['muted'])
        for text in [axis.title, axis.xaxis.label, axis.yaxis.label, *axis.texts]:
            text.set_color(palette['text'])
        for spine in axis.spines.values():
            spine.set_color(palette['border'])
        legend = axis.get_legend()
        if legend is not None:
            legend.get_frame().set_facecolor(palette['surface'])
            legend.get_frame().set_edgecolor(palette['border'])
            for text in legend.get_texts():
                text.set_color(palette['text'])
    st.pyplot(figure, alt=alt)


# Course: L04 – resource caching reuses the connection across Streamlit reruns.
# Clearing this cache creates a new connection; the local app performs transactional writes.
@st.cache_resource
def cached_connection():
    """Return the shared local SQLite connection."""
    return database.get_connection()


# New ratings change the count; edits change the revision. Ordinary reruns reuse the same model.
@st.cache_resource(max_entries=config.ML_MODEL_CACHE_ENTRIES, show_spinner=False)
def cached_recommender(n_ratings, ratings_revision=0, uniclubs_revision=0):
    """Train once per effective rating change and keep at most two models in memory."""
    connection = cached_connection()
    examples = (activity_sources.training_examples(connection)
                if config.UNICLUBS_FEED_ENABLED else [])
    X, y, weights = recommender.build_training_data(connection, public_examples=examples)
    model = recommender.train_production_model(X, y, weights)
    return recommender.Recommender(model, list(X.columns))


# Count plus revision detects new/edited ratings; refresh/reset explicitly clear feature changes.
@st.cache_data(ttl=config.ML_EVALUATION_CACHE_SECONDS, max_entries=config.ML_MODEL_CACHE_ENTRIES,
               show_spinner=False)
def cached_evaluation(n_ratings, ratings_revision=0, uniclubs_revision=0):
    """Evaluate on demand, retaining only two in-memory comparison reports for one hour."""
    connection = cached_connection()
    examples = (activity_sources.training_examples(connection)
                if config.UNICLUBS_FEED_ENABLED else [])
    X, y, _ = recommender.build_training_data(connection, public_examples=examples)
    return recommender.evaluate_models(X, y)


def clear_data_caches():
    """Discard public-data, calendar and model caches after explicit refresh or reset."""
    for cached in (cached_events, cached_calendar, cached_api_available,
                   cached_recommender, cached_evaluation):
        cached.clear()


# This cache stores only status dictionaries; SQLite connections never cross Streamlit threads.
@st.cache_data(ttl=config.UNICLUBS_FEED_CACHE_SECONDS, show_spinner=False)
def cached_uniclubs_refresh(db_file, export_file):
    """Seed an empty independent catalog from the bundled feed, then try the public update."""
    connection = None
    try:
        connection = uniclubs_database.get_connection(db_file)
        uniclubs_database.init_db(connection)
        if uniclubs_feed.get_current_source_success(connection) is None:
            try:
                bundled = uniclubs_refresh.read_public_export(export_file)
                if bundled is not None:
                    uniclubs_feed.apply_public_snapshot(connection, bundled)
            except (ValueError, OSError, sqlite3.Error):
                pass  # An unavailable bundle does not prevent a verified online refresh.
        status = uniclubs_feed.fetch_and_apply(connection)
        status['catalog_available'] = status['source_success_utc'] is not None
        status['event_count'] = connection.execute('SELECT COUNT(*) FROM events').fetchone()[0]
        return status
    except (ValueError, OSError, sqlite3.Error):
        return {'ok': False, 'changed': False, 'source_success_utc': None,
                'checked_at_utc': None, 'catalog_available': False, 'event_count': 0,
                'message': 'UniClubs is unavailable. Other activity sources remain available.'}
    finally:
        if connection is not None:
            connection.close()


def uniclubs_status():
    """Return public feed status without enabling the feed in isolated legacy demo tests."""
    if not config.UNICLUBS_FEED_ENABLED:
        return {'catalog_available': False, 'source_success_utc': None, 'event_count': 0}
    return cached_uniclubs_refresh(str(config.UNICLUBS_DB_FILE), str(config.UNICLUBS_EXPORT_FILE))


def initialize_uniclubs():
    """Refresh once per cache period before the page reads events, tracking its source revision."""
    status = uniclubs_status()
    revision = status['source_success_utc']
    previous = st.session_state.get('ww_uniclubs_source_revision')
    if revision != previous:
        clear_data_caches()
    st.session_state['ww_uniclubs_source_revision'] = revision
    return status


def current_profile(connection, user_id=None):
    """Add source-specific favorites while keeping the public catalog out of the old database."""
    user_id = user_id if user_id is not None else database.get_current_user_id(connection)
    if config.UNICLUBS_FEED_ENABLED:
        return activity_sources.get_profile(connection, user_id)
    return database.get_user_profile(connection, user_id)


def rating_cache_key(connection):
    """Invalidate production/evaluation caches after effective feedback in either source."""
    original = database.get_rating_cache_key(connection)
    revision = (activity_sources.get_rating_revision(connection)
                if config.UNICLUBS_FEED_ENABLED else 0)
    return (*original, revision)


def training_summary(connection, now=None):
    """Count eligible genuine source ratings alongside the existing training summary."""
    summary = database.get_training_summary(connection, now)
    examples = (activity_sources.training_examples(connection, now)
                if config.UNICLUBS_FEED_ENABLED else [])
    summary['Yours'] += len(examples)
    summary['Total'] += len(examples)
    summary['Positive'] += sum(example['rating'] >= config.LABEL_MIN_STARS for example in examples)
    return summary


# Unlike a cache TTL, a native fragment also checks a session that has no user interactions.
@st.fragment(run_every=config.UNICLUBS_FEED_POLL_SECONDS)
def render_uniclubs_status():
    """Show source age and download failures, redrawing the full calendar after an update."""
    if not config.UNICLUBS_FEED_ENABLED:
        return
    status = uniclubs_status()
    revision = status['source_success_utc']
    if revision != st.session_state.get('ww_uniclubs_source_revision'):
        st.session_state['ww_uniclubs_source_revision'] = revision
        clear_data_caches()
        st.rerun(scope='app')
    if revision:
        instant = datetime.fromisoformat(revision.replace('Z', '+00:00'))
        local = calendar_import.to_local_naive(instant)
        st.caption(f'UniClubs: {status["event_count"]} real events')
        st.caption(f'Source updated: {local:%d.%m.%Y %H:%M} Zurich')
        age = (datetime.now(timezone.utc) - instant).total_seconds()
        if age > config.UNICLUBS_FEED_STALE_SECONDS:
            st.warning('UniClubs source data are older than 90 minutes. Check the original page.')
    else:
        st.caption('UniClubs live catalog is not available yet.')
    if status.get('checked_at_utc'):
        checked = datetime.fromisoformat(status['checked_at_utc'].replace('Z', '+00:00'))
        st.caption('Last checked: ' + calendar_import.to_local_naive(checked).strftime('%H:%M'))
    if not status.get('ok', False):
        st.caption(status.get('message', 'Showing the last saved UniClubs catalog.'))
    if st.button('Refresh UniClubs', key='ww_refresh_uniclubs_feed'):
        cached_uniclubs_refresh.clear()
        st.rerun(scope='app')


def render_reset_controls(connection):
    """Reset local database and session state only after the user's confirmation checkbox."""
    reviewed = database.is_reviewed_catalogue(connection)
    label = 'Reset my WeekWise data' if reviewed else 'Reset demo data'
    st.subheader(label)
    if reviewed:
        st.caption('Removes your profile, favorites, plans and ratings. '
                   'The reviewed courses, source evidence and remembered calendar files are kept.')
    else:
        st.caption('Removes your profile, favorites, plans and ratings, then rebuilds the demo. '
                   'Remembered calendar and source files are kept.')
    choice = ('I want to reset my profile and plans' if reviewed
              else 'I want to reset all WeekWise data')
