    if st.button(label, disabled=not confirmed, key='ww_reset_data'):
        # Saved private plans also belong to a reset when the public feed is disabled.
        activity_sources.clear_current_user(connection)
        database.reset_database(connection)
        connection.close()
        clear_data_caches()
        cached_connection.clear()
        st.session_state.clear()
